package com.renkio.game;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.Build;import java.util.Map;
public final class RenkioNotifications {
 private RenkioNotifications(){}
 public static void show(Context context,Map<String,String> data){if(Build.VERSION.SDK_INT>=33&&context.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;String type=data.get("type"),room=data.get("room");if(!("message".equals(type)||"invite".equals(type)||"turn".equals(type))||room==null||!room.matches("[A-F0-9]{6}"))return;
 android.content.SharedPreferences prefs=context.getSharedPreferences("push",Context.MODE_PRIVATE);boolean sound=prefs.getBoolean("audio",true),vibrate=prefs.getBoolean("haptics",true);String channelId="renkio_activity_"+(sound?"s":"q")+(vibrate?"v":"n");NotificationManager manager=context.getSystemService(NotificationManager.class);NotificationChannel channel=new NotificationChannel(channelId,"Renkio oyun bildirimleri",NotificationManager.IMPORTANCE_HIGH);channel.setDescription("Mesajlar, oyun davetleri ve sıra bildirimleri");channel.enableVibration(vibrate);if(!sound)channel.setSound(null,null);manager.createNotificationChannel(channel);
 Uri uri=Uri.parse("https://qwirkle-masa.onrender.com/").buildUpon().appendQueryParameter("room",room).appendQueryParameter("notification",type).build();Intent intent=new Intent(context,MainActivity.class).setData(uri).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);int id=(type+room).hashCode();PendingIntent tap=PendingIntent.getActivity(context,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
 Notification notification=new Notification.Builder(context,channelId).setSmallIcon(com.renkio.game.R.drawable.ic_notification).setContentTitle(data.getOrDefault("title","Renkio")).setContentText(data.getOrDefault("body","Yeni etkinlik var.")).setContentIntent(tap).setAutoCancel(true).setOnlyAlertOnce(true).setCategory("message".equals(type)?Notification.CATEGORY_MESSAGE:Notification.CATEGORY_EVENT).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(new Notification.Builder(context,channelId).setSmallIcon(com.renkio.game.R.drawable.ic_notification).setContentTitle("Renkio").setContentText("Yeni etkinlik var.").build()).build();manager.notify(id,notification);
 }
}
